css:
.absolute {
  position: absolute
}

.relative {
  position: relative
}

.-bottom-24 {
  bottom: -6rem
}

.m-1 {
  margin: 0.25rem
}

.flex {
  display: flex
}

.h-72 {
  height: 18rem
}

.h-8 {
  height: 2rem
}

.w-56 {
  width: 14rem
}

.w-8 {
  width: 2rem
}

.cursor-pointer {
  cursor: pointer
}

.flex-row {
  flex-direction: row
}

.flex-col {
  flex-direction: column
}

.justify-between {
  justify-content: space-between
}

.gap-1 {
  gap: 0.25rem
}

.overflow-hidden {
  overflow: hidden
}

.rounded-2xl {
  border-radius: 1rem
}

.rounded-full {
  border-radius: 9999px
}

.bg-gray-50 {
  --tw-bg-opacity: 1;
  background-color: rgb(249 250 251 / var(--tw-bg-opacity))
}

.bg-lime-400 {
  --tw-bg-opacity: 1;
  background-color: rgb(163 230 53 / var(--tw-bg-opacity))
}

.fill-current {
  fill: currentColor
}

.stroke-current {
  stroke: currentColor
}

.p-2 {
  padding: 0.5rem
}

.p-3 {
  padding: 0.75rem
}

.text-3xl {
  font-size: 1.875rem;
  line-height: 2.25rem
}

.text-xs {
  font-size: 0.75rem;
  line-height: 1rem
}

.font-bold {
  font-weight: 700
}

.text-gray-50 {
  --tw-text-opacity: 1;
  color: rgb(249 250 251 / var(--tw-text-opacity))
}

.text-gray-800 {
  --tw-text-opacity: 1;
  color: rgb(31 41 55 / var(--tw-text-opacity))
}

.text-lime-400 {
  --tw-text-opacity: 1;
  color: rgb(163 230 53 / var(--tw-text-opacity))
}

.text-neutral-800 {
  --tw-text-opacity: 1;
  color: rgb(38 38 38 / var(--tw-text-opacity))
}

.duration-500 {
  transition-duration: 500ms
}

.duration-700 {
  transition-duration: 700ms
}

.hover\:bg-lime-200:hover {
  --tw-bg-opacity: 1;
  background-color: rgb(217 249 157 / var(--tw-bg-opacity))
}

.hover\:duration-700:hover {
  transition-duration: 700ms
}

.group:hover .group-hover\:-bottom-0 {
  bottom: -0px
}
